/* --- speech bubble beside the mouth --- */
let saySide = 'r';
function placeSay() {
  const e = $('#say');
  if (!e || !e.classList.contains('on')) return;
  const s = dims.s * dZk(),
    mx = dogPX(),
    my = mouthY(),
    gap = ((95 * s) / 360) * 100;
  const rR = 100 - (mx + gap) - 2,
    rL = mx - gap - 2;
  if (saySide === 't' || (saySide === 'r' ? rR : rL) < 26) saySide = rR >= rL ? 'r' : 'l';
  const room = saySide === 'r' ? rR : rL;
  let side = room < 26 ? 't' : saySide;
  e.classList.remove('r', 'l', 't');
  e.classList.add(side);
  if (side === 't') {
    e.style.maxWidth = '78%';
    e.style.left = Math.max(20, Math.min(80, mx)) + '%';
    e.style.top = Math.max(4, ((fy() + (92 - PY) * s) / 300) * 100) + '%';
    e.style.setProperty('--tx', '-50%');
    e.style.setProperty('--ty', '-100%');
  } else {
    e.style.maxWidth = room + '%';
    e.style.top = my - 1 + '%';
    e.style.left = (side === 'r' ? mx + gap : mx - gap) + '%';
    e.style.setProperty('--tx', side === 'r' ? '0%' : '-100%');
    e.style.setProperty('--ty', '-50%');
  }
}

