const wxCity = () => (S.trip ? S.trip.c : 'bangkok'),
  wxName = id => (id === 'bangkok' ? 'Bangkok' : id === 'germany' ? 'Frankfurt' : cityName(id));
let WX = null;
function fetchWx() {
  const id = wxCity(),
    g = GEO[id];
  if (!g) return Promise.resolve(null);
  if (WX && WX.id === id && Date.now() - WX.at < 36e5) return Promise.resolve(WX);
  return fetch(
    `https://api.open-meteo.com/v1/forecast?latitude=${g[0]}&longitude=${g[1]}&current=temperature_2m,weather_code&timezone=auto`
  )
    .then(r => (r.ok ? r.json() : null))
    .then(j => {
      if (!j || !j.current) return null;
      WX = { id, t: Math.round(j.current.temperature_2m), c: j.current.weather_code, at: Date.now() };
      return WX;
    })
    .catch(() => null);
}
function wxLine(w) {
  const n = wxName(w.id),
    t = w.t,
    c = w.c;
  if (c >= 95) return `Thunderstorms in ${n} right now. Stay safe inside, Ploy!`;
  if ((c >= 71 && c <= 77) || c === 85 || c === 86)
    return `It's snowing in ${n}! ${t}°C. Just like our market!`;
  if ((c >= 51 && c <= 67) || (c >= 80 && c <= 82))
    return `It's raining in ${n}, ${t}°C. Don't forget your umbrella!`;
  if (c === 45 || c === 48) return `Foggy in ${n} today, ${t}°C. Very mysterious.`;
  if (t <= 5) return `Brrr, it's ${t}°C in ${n}! Wear your warmest coat, Ploy.`;
  if (t <= 14) return `It's ${t}°C in ${n}. Jacket weather!`;
  if (t >= 32) return `It's ${t}°C in ${n}. So hot! Drink lots of water, Ploy.`;
  if (c <= 1) return `${t}°C and sunny in ${n}. Perfect day, Ploy!`;
  return `${t}°C and cloudy in ${n}. A cozy kind of day.`;
}
function sayWx() {
  fetchWx().then(w => {
    if (w && !paneKind && !S.sleep && !br) say(wxLine(w), 5200);
  });
}

